from typing import Any


def task(code: str, spec: str, grade: str, kind: str, title: str,
         prompt: str, criteria: tuple[str, ...], reference: str) -> dict[str, Any]:
    return {
        "code": code, "specialization": spec, "grade": grade,
        "question_type": kind, "title": title,
        "skill": "Рабочие решения" if "WORK" in code else title,
        "question_text": prompt, "rubric_criteria": list(criteria),
        "acceptable_solutions": list(criteria), "reference_solution": reference,
    }


